&= \begin{pmatrix} (-2)(4) & (-2)(-5)+(0)(4) \\ (-5)(4)+(-2)(0) & (-5)(-5)+(0)(4) \end{pmatrix} \\
&= \begin{pmatrix} 8 & 10 \\ -20 & 25 \end{pmatrix}
\end{align*}
