\cos (\pi \sin (\pi u)) &= \sqrt{1-\sin^2(\pi u)} \\
\cos (\pi \sin (\pi u)) &= \sin (\pi \cos x) \\
\pi \sin (\pi u) &= 2n\pi \pm \pi/2, \quad n\in\mathbb{Z}
\end{align*}
